const errorData = $input.first().json;
const wfName = errorData.workflow?.name || 'Неизвестный Workflow';
const nodeName = errorData.node?.name || 'Неизвестный узел';
const errMsg = errorData.error?.message || 'Нет сообщения об ошибке';
const execId = errorData.execution?.id || 'N/A';
const wfId = errorData.workflow?.id || 'N/A';
const baseUrl = 'http://localhost:5678';

const htmlBody = `
  <div style="font-family: Arial, sans-serif; font-size: 14px; color: #333; line-height: 1.6;">
    <h2 style="color: #d9534f; margin-bottom: 20px;">🚨 Ошибка в RAG-пайплайне</h2>
    <table style="border-collapse: collapse; width: 100%; max-width: 600px; margin-bottom: 20px;">
      <tr>
        <td style="padding: 8px; border-bottom: 1px solid #ddd; font-weight: bold; width: 120px;">Воркфлоу:</td>
        <td style="padding: 8px; border-bottom: 1px solid #ddd;">${wfName}</td>
      </tr>
      <tr>
        <td style="padding: 8px; border-bottom: 1px solid #ddd; font-weight: bold;">Узел:</td>
        <td style="padding: 8px; border-bottom: 1px solid #ddd;">${nodeName}</td>
      </tr>
      <tr>
        <td style="padding: 8px; border-bottom: 1px solid #ddd; font-weight: bold;">Сообщение:</td>
        <td style="padding: 8px; border-bottom: 1px solid #ddd; color: #d9534f;">${errMsg}</td>
      </tr>
    </table>
    <a href="${baseUrl}/workflow/${wfId}/executions/${execId}" style="display: inline-block; padding: 10px 15px; background-color: #007bff; color: #ffffff; text-decoration: none; border-radius: 5px;">Открыть Execution в n8n</a>
    <p style="margin-top: 30px; font-size: 12px; color: #888;">Автоматическое сообщение от системы мониторинга WF-3A.</p>
  </div>
`;

return [{ json: { 
  subject: `🚨 СБОЙ: ${wfName}`,
  htmlBody: htmlBody 
}}];
